import { AxisScale } from '@visx/axis';
import { TimeDomain } from '@visx/scale';

import { initialState as annotationsTimeseriesInitialState } from '../../core/components/annotations-timeseries/providers/AnnotationsDataInitialState.js';
import { SelectionState as AnnotationsTimeseriesSelectionState } from '../../core/components/annotations-timeseries/types/state.js';
import { TimeseriesUnit } from '../../core/types/timeseries.js';
import { ZoomKeyboardMode, ZoomMode } from '../../core/types/zoom.js';

export type YAxisScale = {
  scale: AxisScale<number>;
  unit?: TimeseriesUnit;
};
type LeftYScale = { left: YAxisScale; right?: YAxisScale };
type RightYScale = { left?: YAxisScale; right: YAxisScale };
export type YAxisScales = LeftYScale | RightYScale;

export interface TimeseriesZoomState {
  zoomInEnabled: boolean;
  zoomOutEnabled: boolean;
  zoomMode: ZoomMode;
  activeKeyboardMode: ZoomKeyboardMode | undefined;
  keyboardFocusMode: ZoomKeyboardMode | undefined;
}

export interface TimeseriesOverlaysState {
  visibleTooltip: boolean;
  pinnedTooltip: boolean;
}

export interface TimeseriesAnnotationsState {
  selection: AnnotationsTimeseriesSelectionState;
}

export interface TimeseriesThresholdsState {
  hoveredThresholdId: string | undefined;
}

export interface TimeseriesChartState {
  overlays: TimeseriesOverlaysState;
  zoom: TimeseriesZoomState;
  filteredSeriesIds: Set<string>;
  interactionsDisabled: boolean;
  highlightedSeriesIds?: string[];
  annotations: TimeseriesAnnotationsState;
  thresholds: TimeseriesThresholdsState;
  currentDomain?: TimeDomain;
}

export const defaultOverlayValue = {
  visibleTooltip: false,
  pinnedTooltip: false,
};

export const defaultZoomValue: TimeseriesZoomState = {
  zoomInEnabled: true,
  zoomOutEnabled: false,
  zoomMode: 'explore',
  activeKeyboardMode: undefined,
  keyboardFocusMode: undefined,
};

export const initialState: TimeseriesChartState = {
  overlays: defaultOverlayValue,
  zoom: defaultZoomValue,
  filteredSeriesIds: new Set(),
  interactionsDisabled: false,
  highlightedSeriesIds: undefined,
  currentDomain: undefined,
  annotations: annotationsTimeseriesInitialState,
  thresholds: { hoveredThresholdId: undefined },
};
